import type { InteractionSnapshot, ProcessClient } from '@wright/process-client';
import {
  CheckpointCard,
  ProcessUI,
  ProgressPanel,
  ReasonNotice,
  ResultCard,
  Section,
} from '@wright/ui-kit';

export interface AppProps {
  client: ProcessClient;
  snapshot: InteractionSnapshot;
  readOnly: boolean;
}

export default function App({ client, snapshot, readOnly }: AppProps) {
  const outputs = snapshot.outputs ?? [];
  const baseline = outputs.filter(output => output.role.startsWith('baseline_40'));
  const revision = outputs.filter(output => output.role.startsWith('revision_60'));
  const compared = new Set([...baseline, ...revision]);
  const shared = outputs.filter(output => !compared.has(output));
  const interactions = snapshot.interactions ?? [];
  const actions = snapshot.actions ?? [];
  const resultCard = (output: (typeof outputs)[number]) => (
    <ResultCard
      key={output.result_id}
      output={output}
      onNavigate={target => void client.navigate(target)}
      onOpen={reference => void client.navigate({
        kind: 'evidence',
        artifact_ref: reference.artifact_ref,
        result_id: reference.result_id,
      })}
    />
  );

  return <ProcessUI>
    <Section title="Heat-spreader candidate comparison">
      {readOnly && <p>Preview — review the interface before using the process.</p>}
      <ProgressPanel state={snapshot.state} observations={snapshot.observations ?? []} />
      {(snapshot.diagnostics ?? []).map((reason, index) =>
        <ReasonNotice key={`${reason.code}-${index}`} reason={reason} />)}
    </Section>
    <Section title="Candidate results">
      {outputs.length === 0 && <p>Results will appear as the process produces them.</p>}
      <table>
        <caption>Current results grouped by recorded candidate role</caption>
        <thead><tr><th scope="col">Baseline 40</th><th scope="col">Revision 60</th></tr></thead>
        <tbody><tr>
          <td>{baseline.map(resultCard)}</td>
          <td>{revision.map(resultCard)}</td>
        </tr></tbody>
      </table>
      {shared.length > 0 && <section aria-labelledby="shared-results">
        <h3 id="shared-results">Shared evidence and checks</h3>
        {shared.map(resultCard)}
      </section>}
    </Section>
    <Section title="Pending findings and review">
      {interactions.length === 0 && <p>
        No declared checkpoint is exposed in the current snapshot. This does not establish
        engineering acceptance; review the diagnostics and assessments shown with the results.
      </p>}
      {interactions.map((interaction, index) =>
        <CheckpointCard key={index} interaction={interaction} actions={actions} />)}
      <p>No artifact-specific viewer or mutation control is included in this compact comparison.</p>
    </Section>
  </ProcessUI>;
}
